import React, { useState } from "react";
import { Dialog } from "@headlessui/react"; // Importing Dialog
import { ExclamationTriangleIcon } from "@heroicons/react/24/outline";

// Add the missing imports for DialogBackdrop, DialogPanel, and DialogTitle
import { DialogBackdrop, DialogPanel, DialogTitle } from "@headlessui/react";

export default function LaptopsList() {
  const [laptops, setLaptops] = useState([
    {
      id: 1,
      serialNumber: "SN12345",
      studentName: "John Doe",
      description: "Screen flickers occasionally",
      urgency: "High",
      status: "In Maintenance",
    },
    {
      id: 2,
      serialNumber: "SN67890",
      studentName: "Jane Smith",
      description: "Battery drains quickly",
      urgency: "Medium",
      status: "In Maintenance",
    },
  ]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedLaptop, setSelectedLaptop] = useState(null);

  const updateStatus = (id, newStatus) => {
    const updatedLaptops = laptops.map((laptop) =>
      laptop.id === id ? { ...laptop, status: newStatus } : laptop
    );
    setLaptops(updatedLaptops);
  };

  const handleMarkAsRepaired = (laptop) => {
    setSelectedLaptop(laptop);
    setIsModalOpen(true);
  };

  const handleConfirmRepair = () => {
    if (selectedLaptop) {
      updateStatus(selectedLaptop.id, "Repaired");
      setIsModalOpen(false);
      setSelectedLaptop(null);
    }
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedLaptop(null);
  };

  return (
    <div className="p-8 space-y-8 bg-gray-50 min-h-screen">
      <h2 className="text-2xl font-semibold text-gray-900">
        Laptops Under Maintenance
      </h2>
      <p className="text-sm text-gray-600">
        Below is the list of laptops currently marked for maintenance.
      </p>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white rounded-lg shadow-sm">
          <thead className="bg-indigo-600 text-white">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Serial Number
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Student Name
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Description
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Urgency
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Status
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {laptops.map((laptop) => (
              <tr key={laptop.id} className="hover:bg-gray-100">
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.serialNumber}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.studentName}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.description}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  <span
                    className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                      laptop.urgency === "High"
                        ? "bg-red-100 text-red-800"
                        : laptop.urgency === "Medium"
                        ? "bg-yellow-100 text-yellow-800"
                        : "bg-green-100 text-green-800"
                    }`}
                  >
                    {laptop.urgency}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.status}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm">
                  <button
                    onClick={() => handleMarkAsRepaired(laptop)}
                    className="rounded-md bg-indigo-600 px-3 py-1 text-white text-sm font-semibold hover:bg-indigo-500"
                  >
                    Mark as Repaired
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal for confirming repair */}
      {isModalOpen && selectedLaptop && (
        <Dialog
          open={isModalOpen}
          onClose={handleCloseModal}
          className="relative z-10"
        >
          <DialogBackdrop
            transition
            className="fixed inset-0 bg-gray-500/75 transition-opacity data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in"
          />
          <div className="fixed inset-0 z-10 w-screen overflow-y-auto">
            <div className="flex min-h-full items-end justify-center p-4 text-center sm:items-center sm:p-0">
              <DialogPanel
                transition
                className="relative transform overflow-hidden rounded-lg bg-white text-left shadow-xl transition-all data-[closed]:translate-y-4 data-[closed]:opacity-0 data-[enter]:duration-300 data-[leave]:duration-200 data-[enter]:ease-out data-[leave]:ease-in sm:my-8 sm:w-full sm:max-w-lg data-[closed]:sm:translate-y-0 data-[closed]:sm:scale-95"
              >
                <div className="bg-white px-4 pb-4 pt-5 sm:p-6 sm:pb-4">
                  <div className="sm:flex sm:items-start">
                    <div className="mx-auto flex size-12 shrink-0 items-center justify-center rounded-full bg-red-100 sm:mx-0 sm:size-10">
                      <ExclamationTriangleIcon
                        aria-hidden="true"
                        className="size-6 text-red-600"
                      />
                    </div>
                    <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
                      <DialogTitle
                        as="h3"
                        className="text-base font-semibold text-gray-900"
                      >
                        Mark Laptop as Repaired
                      </DialogTitle>
                      <div className="mt-2">
                        <p className="text-sm text-gray-500">
                          Are you sure you want to mark the laptop with serial
                          number {selectedLaptop.serialNumber} as repaired? This
                          action will update its status.
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
                <div className="bg-gray-50 px-4 py-3 sm:flex sm:flex-row-reverse sm:px-6">
                  <button
                    type="button"
                    onClick={handleConfirmRepair}
                    className="inline-flex w-full justify-center rounded-md bg-green-600 px-3 py-2 text-sm font-semibold text-white shadow-sm hover:bg-green-500 sm:ml-3 sm:w-auto"
                  >
                    Yes, Mark as Repaired
                  </button>
                  <button
                    type="button"
                    onClick={handleCloseModal}
                    className="mt-3 inline-flex w-full justify-center rounded-md bg-white px-3 py-2 text-sm font-semibold text-gray-900 shadow-sm ring-1 ring-inset ring-gray-300 hover:bg-gray-50 sm:mt-0 sm:w-auto"
                  >
                    Cancel
                  </button>
                </div>
              </DialogPanel>
            </div>
          </div>
        </Dialog>
      )}
    </div>
  );
}
